**Version Used**: 
Different

**Steps to Reproduce**:

```cs
    using System;
    using System.Linq;
    using System.Threading;
    using System.Threading.Tasks;
    using Microsoft.CodeAnalysis;
    using Microsoft.CodeAnalysis.CSharp;
    using Microsoft.CodeAnalysis.CSharp.Syntax;
    using Microsoft.CodeAnalysis.Editing;
    using Microsoft.CodeAnalysis.Formatting;
    using Microsoft.CodeAnalysis.Simplification;
    using NUnit.Framework;

    public class Repro
    {
        [Test]
        public async Task MakeSealed()
        {
            var testCode = @"
namespace RoslynSandbox
{
    public class Foo
    {
    }
}";

            var projectId = ProjectId.CreateNewId("Test");
            var sln = new AdhocWorkspace()
                .CurrentSolution
                .AddProject(projectId, "Test", "Test", LanguageNames.CSharp)
                .WithProjectCompilationOptions(
                    projectId,
                    new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, allowUnsafe: true))
                .AddDocument(DocumentId.CreateNewId(projectId), "Foo.cs", testCode);

            var editor = await DocumentEditor.CreateAsync(sln.Projects.First().Documents.First()).ConfigureAwait(false);
            var type = ((CompilationUnitSyntax)editor.OriginalRoot)
                .Members.OfType<NamespaceDeclarationSyntax>()
                .First()
                .Members.OfType<ClassDeclarationSyntax>()
                .First();
            editor.SetModifiers(type, DeclarationModifiers.From(editor.SemanticModel.GetDeclaredSymbol(type)).WithIsSealed(isSealed: true));
            var expected = @"
namespace RoslynSandbox
{
    public sealed class Foo
    {
    }
}";
            var actual = await GetCodeAsync(editor.GetChangedDocument(), CancellationToken.None);
            Console.Write(actual);
            Assert.AreEqual(expected, actual);
        }

        private static async Task<string> GetCodeAsync(Document document, CancellationToken cancellationToken)
        {
            var simplifiedDoc = await Simplifier.ReduceAsync(document, Simplifier.Annotation, cancellationToken: cancellationToken).ConfigureAwait(false);
            var formatted = await Formatter.FormatAsync(simplifiedDoc, Formatter.Annotation, cancellationToken: cancellationToken).ConfigureAwait(false);
            var sourceText = await formatted.GetTextAsync(cancellationToken).ConfigureAwait(false);
            return sourceText.ToString();
        }
    }
```

Prints:

```
namespace RoslynSandbox
{
    public sealedclass Foo
    {
    }
}
```

**Expected Behavior**:

I expected the formatter to format `public sealedclass Foo`, chances are I used it wrong. Writing this issue any way in case it is a repro for a real bug.

